-- 2) Create an Agent job calling the IndexOptimize procedure with smart thresholds
EXECUTE dbo.IndexOptimize
    @Databases = 'USER_DATABASES',
    @FragmentationLow = NULL,
    @FragmentationMedium = 'INDEX_REORGANIZE,INDEX_REBUILD_ONLINE,INDEX_REBUILD_OFFLINE',
    @FragmentationHigh = 'INDEX_REBUILD_ONLINE,INDEX_REBUILD_OFFLINE',
    @FragmentationLevel1 = 5,
    @FragmentationLevel2 = 30,
    @UpdateStatistics = 'ALL',
    @OnlyModifiedStatistics = 'Y',
    @TimeLimit = 7200,
    @LogToTable = 'Y';

$instances = Get-Content -Path 'C:\DBA\instance-list.txt'
$results = foreach ($instance in $instances) {
    try {
        $dbs = Get-DbaDatabase -SqlInstance $instance -ExcludeSystem -ErrorAction Stop
        foreach ($db in $dbs) {
            try {
                $backup = Backup-DbaDatabase -SqlInstance $instance -Database $db.Name `
                    -Type Full -CompressBackup -Path '\\backupshare\sql' -ErrorAction Stop
                $verify = Test-DbaLastBackup -SqlInstance $instance -Database $db.Name -ErrorAction Stop
                [PSCustomObject]@{
                    Instance = $instance; Database = $db.Name
                    BackupFile = $backup.BackupPath; Verified = $verify.RestoreResult
                    Status = 'Success'; Error = $null
                }
            } catch {
                [PSCustomObject]@{
                    Instance = $instance; Database = $db.Name
                    BackupFile = $null; Verified = $null
                    Status = 'Failed'; Error = $_.Exception.Message
                }
            }
        }
    } catch {
        [PSCustomObject]@{
            Instance = $instance; Database = '<connection failed>'
            BackupFile = $null; Verified = $null
            Status = 'Failed'; Error = $_.Exception.Message
        }
    }
}
$results | Export-Csv -Path 'C:\DBA\backup-run-log.csv' -NoTypeInformation
$failures = $results | Where-Object Status -eq 'Failed'
if ($failures) {
    Send-MailMessage -To 'dba-team@company.com' -Subject "Backup run: $($failures.Count) failures" `
        -Body ($failures | Out-String) -SmtpServer 'smtp.company.com' -From 'sqlagent@company.com'
}

